-- ---------------------------------------------------------------- foreign keys
-- added last, so this file runs on an empty database in any table order
-- and every statement is guarded - re-running it changes nothing. An existing
-- constraint with a different ON DELETE action is rebuilt, so an older project
-- picks up the safer 'set null' behaviour for manager/reviewer/approver columns.

do $$ begin
  if exists (select 1 from pg_constraint c join pg_class r on r.oid = c.conrelid
                 where r.relname = 'departments' and c.conname = 'departments_head_id_fkey' and c.confdeltype <> 's') then
    execute 'alter table departments drop constraint departments_head_id_fkey';   -- wrong ON DELETE, rebuild it
  end if;
  if not exists (select 1 from pg_constraint c join pg_class r on r.oid = c.conrelid
                 where r.relname = 'departments' and c.conname = 'departments_head_id_fkey') then
    begin
      alter table departments add constraint departments_head_id_fkey
        foreign key (head_id) references employees (id) on delete set null;
    exception when foreign_key_violation then
      raise notice 'departments.head_id has rows that do not match employees(id) - the foreign key was not created; clean the orphan ids and run this file again';
      raise warning 'departments.head_id: foreign key skipped because existing rows violate it';
    end;
  end if;
end $$;
