-- RLS: the Flask server is the only client and it uses the service_role key (which bypasses RLS),
-- so the tables stay private to the API by default. Add authenticated policies if you ever query
-- these tables straight from a browser.
do $$
declare t text;
begin
  for t in select unnest(array['departments', 'designations', 'employees', 'shifts', 'attendance', 'attendance_regularizations', 'leave_types', 'leave_balances', 'leave_requests', 'holidays', 'payroll_structures', 'payslips', 'reimbursements', 'jobs', 'candidates', 'projects', 'timesheets', 'timesheet_entries', 'goals', 'performance_reviews', 'feedbacks', 'checkins', 'announcements', 'documents', 'document_requests'])::text loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists "hrms_service_role" on %I', t);
    execute format('create policy "hrms_service_role" on %I for all to service_role using (true) with check (true)', t);
  end loop;
end $$;

grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to service_role;

-- triggers + indexes are re-created idempotently
comment on table departments is 'Org structure - departments and their head.';
drop trigger if exists departments_updated_at on departments;
create trigger departments_updated_at before update on departments for each row execute function set_updated_at();
comment on table designations is 'Job titles, optionally scoped to a department.';
drop trigger if exists designations_updated_at on designations;
create trigger designations_updated_at before update on designations for each row execute function set_updated_at();
comment on table employees is 'Core people record. `department`/`designation`/`manager` are optional display copies.';
drop trigger if exists employees_updated_at on employees;
create trigger employees_updated_at before update on employees for each row execute function set_updated_at();
create index if not exists employees_department_id_idx on employees (department_id);
create index if not exists employees_manager_id_idx on employees (manager_id);
create index if not exists employees_status_idx on employees (status);
comment on table shifts is 'Working hours + grace period used for lateness.';
drop trigger if exists shifts_updated_at on shifts;
create trigger shifts_updated_at before update on shifts for each row execute function set_updated_at();
comment on table attendance is 'One row per employee per day. clock_in / clock_out are TIME values (the date lives in `date`).';
drop trigger if exists attendance_updated_at on attendance;
create trigger attendance_updated_at before update on attendance for each row execute function set_updated_at();
create index if not exists attendance_employee_id_idx on attendance (employee_id);
create index if not exists attendance_date_idx on attendance (date);
create index if not exists attendance_status_idx on attendance (status);
comment on table attendance_regularizations is 'Employee requests to fix a punch; `reason` is mandatory.';
drop trigger if exists attendance_regularizations_updated_at on attendance_regularizations;
create trigger attendance_regularizations_updated_at before update on attendance_regularizations for each row execute function set_updated_at();
create index if not exists attendance_regularizations_employee_id_status_idx on attendance_regularizations (employee_id, status);
comment on table leave_types is 'Configurable quotas (Casual, Sick, Earned, WFH, Optional Holiday).';
drop trigger if exists leave_types_updated_at on leave_types;
create trigger leave_types_updated_at before update on leave_types for each row execute function set_updated_at();
comment on table leave_balances is 'Per employee, per type, per year quota. `pending` is recomputed from requests on read.';
drop trigger if exists leave_balances_updated_at on leave_balances;
create trigger leave_balances_updated_at before update on leave_balances for each row execute function set_updated_at();
create index if not exists leave_balances_employee_id_idx on leave_balances (employee_id);
comment on table leave_requests is 'Applications and their approval trail.';
drop trigger if exists leave_requests_updated_at on leave_requests;
create trigger leave_requests_updated_at before update on leave_requests for each row execute function set_updated_at();
create index if not exists leave_requests_employee_id_status_idx on leave_requests (employee_id, status);
create index if not exists leave_requests_start_date_idx on leave_requests (start_date);
comment on table holidays is 'Company calendar; blocks leave bookings and attendance expectations.';
drop trigger if exists holidays_updated_at on holidays;
create trigger holidays_updated_at before update on holidays for each row execute function set_updated_at();
create index if not exists holidays_date_idx on holidays (date);
comment on table payroll_structures is 'Monthly components per employee, effective from a date.';
drop trigger if exists payroll_structures_updated_at on payroll_structures;
create trigger payroll_structures_updated_at before update on payroll_structures for each row execute function set_updated_at();
comment on table payslips is 'One row per employee per month; the PDF lives in Storage (`payslip_url`).';
drop trigger if exists payslips_updated_at on payslips;
create trigger payslips_updated_at before update on payslips for each row execute function set_updated_at();
create index if not exists payslips_year_month_idx on payslips (year, month);
comment on table reimbursements is 'Expense claims with receipt links.';
drop trigger if exists reimbursements_updated_at on reimbursements;
create trigger reimbursements_updated_at before update on reimbursements for each row execute function set_updated_at();
create index if not exists reimbursements_employee_id_status_idx on reimbursements (employee_id, status);
comment on table jobs is 'Open requisitions.';
drop trigger if exists jobs_updated_at on jobs;
create trigger jobs_updated_at before update on jobs for each row execute function set_updated_at();
create index if not exists jobs_status_idx on jobs (status);
comment on table candidates is 'Pipeline rows; `converted_employee_id` links a hire back to `employees`.';
drop trigger if exists candidates_updated_at on candidates;
create trigger candidates_updated_at before update on candidates for each row execute function set_updated_at();
create index if not exists candidates_job_id_stage_idx on candidates (job_id, stage);
create index if not exists candidates_stage_idx on candidates (stage);
comment on table projects is 'Where timesheets are booked, plus the billing rate used for utilisation value.';
drop trigger if exists projects_updated_at on projects;
create trigger projects_updated_at before update on projects for each row execute function set_updated_at();
comment on table timesheets is 'Weekly roll-up (Draft -> Submitted -> Approved/Rejected).';
drop trigger if exists timesheets_updated_at on timesheets;
create trigger timesheets_updated_at before update on timesheets for each row execute function set_updated_at();
create index if not exists timesheets_employee_id_week_starting_idx on timesheets (employee_id, week_starting);
create index if not exists timesheets_status_idx on timesheets (status);
comment on table timesheet_entries is 'The individual day/project rows behind a timesheet.';
drop trigger if exists timesheet_entries_updated_at on timesheet_entries;
create trigger timesheet_entries_updated_at before update on timesheet_entries for each row execute function set_updated_at();
create index if not exists timesheet_entries_timesheet_id_idx on timesheet_entries (timesheet_id);
create index if not exists timesheet_entries_employee_id_date_idx on timesheet_entries (employee_id, date);
create index if not exists timesheet_entries_project_id_idx on timesheet_entries (project_id);
comment on table goals is 'OKR-style objectives with a progress percentage.';
drop trigger if exists goals_updated_at on goals;
create trigger goals_updated_at before update on goals for each row execute function set_updated_at();
create index if not exists goals_employee_id_status_idx on goals (employee_id, status);
comment on table performance_reviews is 'Self + manager review per cycle; competencies are a jsonb score card.';
drop trigger if exists performance_reviews_updated_at on performance_reviews;
create trigger performance_reviews_updated_at before update on performance_reviews for each row execute function set_updated_at();
create index if not exists performance_reviews_employee_id_idx on performance_reviews (employee_id);
create index if not exists performance_reviews_reviewer_id_status_idx on performance_reviews (reviewer_id, status);
comment on table feedbacks is 'Peer-to-peer kudos. `tags` is a comma separated list; `is_anonymous` hides the sender.';
drop trigger if exists feedbacks_updated_at on feedbacks;
create trigger feedbacks_updated_at before update on feedbacks for each row execute function set_updated_at();
create index if not exists feedbacks_to_employee_id_idx on feedbacks (to_employee_id);
comment on table checkins is '1:1 notes between a manager and an employee.';
drop trigger if exists checkins_updated_at on checkins;
create trigger checkins_updated_at before update on checkins for each row execute function set_updated_at();
create index if not exists checkins_employee_id_date_idx on checkins (employee_id, date);
comment on table announcements is 'Company-wide notices shown on Home.';
drop trigger if exists announcements_updated_at on announcements;
create trigger announcements_updated_at before update on announcements for each row execute function set_updated_at();
create index if not exists announcements_date_idx on announcements (date);
comment on table documents is 'Employee files: why they were collected, who uploaded them and who may see them.';
drop trigger if exists documents_updated_at on documents;
create trigger documents_updated_at before update on documents for each row execute function set_updated_at();
create index if not exists documents_employee_id_status_idx on documents (employee_id, status);
create index if not exists documents_doc_type_idx on documents (doc_type);
create index if not exists documents_valid_till_idx on documents (valid_till);
comment on table document_requests is 'HR chasing a document from an employee, with a due date.';
drop trigger if exists document_requests_updated_at on document_requests;
create trigger document_requests_updated_at before update on document_requests for each row execute function set_updated_at();
create index if not exists document_requests_employee_id_status_idx on document_requests (employee_id, status);

-- reference data: inserted only while a table is still empty, so nothing you already
-- have on file is duplicated or overwritten.
-- departments (8 rows) - inserted only while the table is empty
do $$ begin
  if exists (select 1 from departments limit 1) then return; end if;
  insert into departments (description, name) values ('Leadership and strategy', 'Executive');
  insert into departments (description, name) values ('Product and platform engineering', 'Engineering');
  insert into departments (description, name) values ('Product design and research', 'Design');
  insert into departments (description, name) values ('People ops, hiring and engagement', 'Human Resources');
  insert into departments (description, name) values ('Revenue, partnerships and customer growth', 'Sales');
  insert into departments (description, name) values ('Brand, content and demand generation', 'Marketing');
  insert into departments (description, name) values ('Accounts, payroll and compliance', 'Finance');
  insert into departments (description, name) values ('Admin, IT and facilities', 'Operations');
end $$;

